import { assertSize, assertRandomTarget } from './utils/assertSize.mjs'
import { fromUint8Super } from './utils/output.mjs'

const { crypto, Buffer } = globalThis // Buffer required only for randomBytes

/** @deprecated Use `import { randomValues } from '@exodus/crypto/randomBytes'` */
export function randomBytes(size) {
  assertSize(size)
  const buffer = Buffer.alloc(size)
  crypto.getRandomValues(buffer)
  return buffer
}

const MAX_BYTES = 65536
export function randomFill(arr) {
  assertRandomTarget(arr)
  if (arr.byteLength <= MAX_BYTES) {
    crypto.getRandomValues(arr) // Fast path
  } else {
    const [start, end] = [arr.byteOffset, arr.byteOffset + arr.byteLength]
    for (let pos = start; pos < end; pos += MAX_BYTES) {
      crypto.getRandomValues(new Uint8Array(arr.buffer, pos, Math.min(end - pos, MAX_BYTES)))
    }
  }
  return arr
}

export function randomValues(size, format = 'uint8') {
  assertSize(size)
  return fromUint8Super(randomFill(new Uint8Array(size)), format)
}
